<?php use Namira\StoreCatalog; ?>
<div class="store-grid"><?php foreach($result['items'] as $p): ?><article class="store-card" data-card-id="<?= (int)$p['id'] ?>"><a href="<?= e(url('product',['id'=>$p['id']])) ?>"><?php if($p['cover_id']||$p['image_id']): ?><img loading="lazy" width="400" height="400" src="<?= e($p['cover_id']?url('store-media',['id'=>$p['cover_id']]):url('media',['id'=>$p['image_id']])) ?>" alt="<?= e($p['title']) ?>"><?php else: ?><div class="store-placeholder" aria-hidden="true">ن</div><?php endif ?><div class="store-card-content"><?php if($p['production']==='custom'): ?><span class="store-badge">قابل شخصی‌سازی</span><?php endif ?><p class="muted"><?= e(StoreCatalog::DELIVERY[$p['delivery']]) ?></p><h2><?= e($p['title']) ?></h2><p class="price"><?php if($p['pricing']==='quote'): ?>استعلام قیمت<?php else: ?><?= $p['pricing']==='variable'?'از ':'' ?><?= fa(number_format((int)$p['min_price'])) ?> <small>تومان</small><?php endif ?></p><p class="muted"><?= $p['available']?'مشاهده و انتخاب گزینه‌ها':'مشاهده محصول' ?></p></div></a></article><?php endforeach ?></div>